// Reciter catalog with every moshaf (generated by scripts/convert-reciters.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export type Moshaf = {
  id: number;
  name: string;
  nameEn: string;
  server: string;
  total: number;
  /** Inclusive [from, to] surah ranges available on the server. */
  surahs: [number, number][];
};

export type ReciterEntry = { id: number; name: string; nameEn: string; moshaf: Moshaf[] };

export const getAllReciters = cache(async (): Promise<ReciterEntry[]> =>
  JSON.parse(await fs.readFile(path.join(process.cwd(), "data/reciters/reciters.json"), "utf8")),
);
